const projects={itsu:{title:'Itsu',meta:'iPHONE APP / iOS 17+',lead:'最後にやったの、いつ？',description:'毎日ではない出来事の最終実施日を、すぐに残すためのiPhoneアプリ。正確な日を思い出せないときも、記憶のあいまいさを保って記録できます。',features:['「今日やった」を1タップで記録','「先週ごろ」「月の上旬」のような期間でも記録','前回からの経過日数と、過去の履歴を確認','SwiftUI / SwiftData / StoreKit 2'],note:'アカウント不要。記録は端末内に保存し、広告・追跡・解析SDKを使用しません。',alt:'Itsuのホーム画面を紹介する画像'},oki:{title:'Oki',meta:'iPHONE APP / 開発中',lead:'明日の朝を、逆算する。',description:'予定と朝の準備時間から起床時刻を逆算する、iPhone向けのスマートアラームです。',features:['次のアラームをホームで確認','朝の準備時間に合わせた起床時刻の計算','カレンダーから単発アラームを予約・解除','SwiftUI / iOS 26以降 / Liquid Glass'],note:'現在、公開に向けて開発中です。表示している画面は開発時点のもので、公開版では変更される場合があります。',alt:'Okiの開発中のホーム画面'}};
const dialog=document.querySelector('#product-dialog');let trigger;
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{trigger=button;const key=button.dataset.project,p=projects[key];for(const field of ['title','meta','lead','description','note'])document.getElementById('dialog-'+field).textContent=p[field];const screen=document.getElementById('dialog-screen');screen.src='assets/'+key+'-screen.png';screen.alt=p.alt;document.getElementById('dialog-features').replaceChildren(...p.features.map(text=>{const li=document.createElement('li');li.textContent=text;return li}));document.getElementById('dialog-support').hidden=key!=='itsu';dialog.showModal();dialog.scrollTop=0}));
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>trigger?.focus());
